/**
 * Cross-evaluation reuse, retention and adaptive admission of {@link OptionalRightMemo}. A nested OPTIONAL is opened
 * once per outer row, so completed runs must survive across {@code open} calls.
 */
class OptionalRightMemoSharingTest {

	private static final String NS = "http://example.com/";

	private static final ReplayValueCapturer CAPTURER = new ReplayValueCapturer() {
		@Override
		public Value apply(Value value) {
			return value;
		}

		@Override
		public long canonicalId(Value value) {
			return value.stringValue().hashCode() & 0x7fffffffL;
		}
	};

	private final AtomicInteger rightEvaluations = new AtomicInteger();
	private final AtomicBoolean snapshotValid = new AtomicBoolean(true);

	private static LeftJoin join() {
		return new LeftJoin(new SingletonSet(), new Join(
				new StatementPattern(Var.of("key"), Var.of("p1"), Var.of("child")),
				new StatementPattern(Var.of("child"), Var.of("p2"), Var.of("result"))));
	}

	private OptionalRightMemo memo() {
		return OptionalRightMemo.prepare(join(), new QueryEvaluationContext.Minimal(null), () -> {
			if (!snapshotValid.get()) {
				throw new IllegalStateException("snapshot is no longer valid");
			}
		}, CAPTURER);
	}

	private static BindingSet leftRow(String key) {
		QueryBindingSet row = new QueryBindingSet();
		if (key != null) {
			row.setBinding("key", SimpleValueFactory.getInstance().createIRI(NS + key));
		}
		return row;
	}

	private static QueryEvaluationStep left(List<String> keys) {
		return ignored -> {
			List<BindingSet> rows = new ArrayList<>();
			keys.forEach(key -> rows.add(leftRow(key)));
			return new CloseableIteratorIteration<>(rows.iterator());
		};
	}

	/** Right operand that counts evaluations and yields {@code fanOut(key)} rows per key (1 row when unbound). */
	private QueryEvaluationStep right(IntFunction<Integer> fanOut) {
		return row -> {
			rightEvaluations.incrementAndGet();
			Value key = row.getValue("key");
			int rows = key == null ? 1 : fanOut.apply(key.stringValue().hashCode());
			List<BindingSet> out = new ArrayList<>();
			for (int i = 0; i < rows; i++) {
				QueryBindingSet merged = new QueryBindingSet(row);
				merged.setBinding("child", SimpleValueFactory.getInstance().createIRI(NS + "child" + i));
				merged.setBinding("result", SimpleValueFactory.getInstance()
						.createLiteral(
								key == null ? "none" : key.stringValue() + "#" + i));
				out.add(merged);
			}
			return new CloseableIteratorIteration<>(out.iterator());
		};
	}

	private static List<BindingSet> run(OptionalRightMemo memo, List<String> keys, QueryEvaluationStep right) {
		try (CloseableIteration<BindingSet> rows = memo.open(left(keys), EmptyBindingSet.getInstance(), right)) {
			return QueryResults.asList(rows);
		}
	}

	private static List<BindingSet> reference(List<String> keys, QueryEvaluationStep right) {
		List<BindingSet> out = new ArrayList<>();
		for (String key : keys) {
			try (var rows = right.evaluate(leftRow(key))) {
				out.addAll(QueryResults.asList(rows));
			}
		}
		return out;
	}

	@Test
	void completedRunsAreReusedAcrossOpens() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 1);
		List<String> keys = List.of("a", "b", "a", "b");

		List<BindingSet> first = run(memo, keys, right);
		assertThat(rightEvaluations).hasValue(2);
		List<BindingSet> second = run(memo, keys, right);

		assertThat(rightEvaluations).as("second open must replay").hasValue(2);
		assertThat(second).isEqualTo(first);
	}

	@Test
	void resultsMatchUncachedEvaluationIncludingDuplicatesAndUnboundKeys() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 1 + Math.abs(h) % 3);
		List<String> keys = new ArrayList<>();
		for (int i = 0; i < 200; i++) {
			keys.add(i % 7 == 0 ? null : "k" + (i % 11));
		}
		List<BindingSet> expected = reference(keys, right);
		rightEvaluations.set(0);

		for (int round = 0; round < 3; round++) {
			assertThat(run(memo, keys, right)).isEqualTo(expected);
		}
		assertThat(rightEvaluations.get()).isLessThanOrEqualTo(12);
	}

	@Test
	void smallHotEntriesSurviveLargeRuns() {
		OptionalRightMemo memo = memo();
		// "hot" has one row, every other key has a run of 1000 rows
		int hot = (NS + "hot").hashCode();
		QueryEvaluationStep right = right(h -> h == hot ? 1 : 1000);
		List<String> keys = new ArrayList<>();
		keys.add("hot");
		for (int i = 0; i < 60; i++) {
			keys.add("big" + i);
		}
		run(memo, keys, right);
		int afterFirst = rightEvaluations.get();
		assertThat(afterFirst).isEqualTo(61);

		run(memo, List.of("hot"), right);

		assertThat(rightEvaluations).as("small hot entry must not be evicted by large runs").hasValue(afterFirst);
	}

	@Test
	void uniqueKeysDisableCapturingWithoutChangingResults() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 1);
		List<String> keys = new ArrayList<>();
		for (int i = 0; i < 20_000; i++) {
			keys.add("unique" + i);
		}
		List<BindingSet> expected = reference(keys, right);

		assertThat(run(memo, keys, right)).isEqualTo(expected);
		assertThat(memo.isDisabled()).isTrue();
		assertThat(memo.retainedEntries()).isZero();

		List<String> repeated = List.of("unique1", "unique1", "unique2");
		assertThat(run(memo, repeated, right)).isEqualTo(reference(repeated, right));
	}

	@Test
	void repeatedKeysKeepCapturingEnabled() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 1);
		List<String> keys = new ArrayList<>();
		for (int i = 0; i < 20_000; i++) {
			keys.add("key" + (i % 100));
		}
		run(memo, keys, right);

		assertThat(memo.isDisabled()).isFalse();
		assertThat(rightEvaluations).hasValue(100);
	}

	@Test
	void cancelledPartialRunIsNotPublished() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 3);
		try (CloseableIteration<BindingSet> rows = memo.open(left(List.of("a")), EmptyBindingSet.getInstance(),
				right)) {
			assertThat(rows.hasNext()).isTrue();
			rows.next();
		}
		assertThat(rightEvaluations).hasValue(1);

		assertThat(run(memo, List.of("a"), right)).hasSize(3);

		assertThat(rightEvaluations).as("partial run must not be replayed").hasValue(2);
	}

	@Test
	void snapshotCheckGuardsReuseAcrossOpens() {
		OptionalRightMemo memo = memo();
		QueryEvaluationStep right = right(h -> 1);
		run(memo, List.of("a"), right);

		snapshotValid.set(false);

		assertThatThrownBy(() -> run(memo, List.of("a"), right)).isInstanceOf(IllegalStateException.class);
	}
}
